func (l *SPL2Lexer) openBrace() { l.braceDepth++; l.PushMode(antlr.LexerDefaultMode) }
func (l *SPL2Lexer) closeBrace() {
	if l.braceDepth > 0 {
		l.braceDepth--
		l.PopMode()
	}
}

func (l *SPL2Lexer) Action(localctx antlr.RuleContext, ruleIndex, actionIndex int) {
	switch ruleIndex {
	case 110:
		l.LBRACE_Action(localctx, actionIndex)

	case 111:
		l.RBRACE_Action(localctx, actionIndex)

	case 123:
		l.STRING_INTERPOLATION_Action(localctx, actionIndex)

	case 127:
		l.NAME_INTERPOLATION_Action(localctx, actionIndex)

	default:
		panic("No registered action for: " + fmt.Sprint(ruleIndex))
	}
}

func (l *SPL2Lexer) LBRACE_Action(localctx antlr.RuleContext, actionIndex int) {
	switch actionIndex {
	case 0:
		l.openBrace()

	default:
		panic("No registered action for: " + fmt.Sprint(actionIndex))
	}
}
func (l *SPL2Lexer) RBRACE_Action(localctx antlr.RuleContext, actionIndex int) {
	switch actionIndex {
	case 1:
		l.closeBrace()

	default:
		panic("No registered action for: " + fmt.Sprint(actionIndex))
	}
}
func (l *SPL2Lexer) STRING_INTERPOLATION_Action(localctx antlr.RuleContext, actionIndex int) {
	switch actionIndex {
	case 2:
		l.openBrace()

	default:
		panic("No registered action for: " + fmt.Sprint(actionIndex))
	}
}
func (l *SPL2Lexer) NAME_INTERPOLATION_Action(localctx antlr.RuleContext, actionIndex int) {
	switch actionIndex {
	case 3:
		l.openBrace()

	default:
		panic("No registered action for: " + fmt.Sprint(actionIndex))
	}
}
